import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Client } from '@stomp/stompjs';
import SockJS from 'sockjs-client';
import {
  ArrowLeft, Plane, Truck, Sparkles, Send, Gauge, SatelliteDish,
  BatteryFull, BatteryMedium, BatteryLow, BatteryWarning, Route
} from 'lucide-react';
import ThemeToggle from './ThemeToggle';
import { useTheme } from '../context/ThemeContext';
import FleetMap from './FleetMap';

// NEW: A vibrant color palette for unique vehicle assignment
const VEHICLE_COLORS = ['#FF3366', '#00E5FF', '#00E676', '#FF9100', '#D500F9', '#FFEA00', '#2979FF'];

export const getVehicleColor = (vId) => {
  let hash = 0;
  for (let i = 0; i < (vId || '').length; i++) {
    hash = vId.charCodeAt(i) + ((hash << 5) - hash);
  }
  return VEHICLE_COLORS[Math.abs(hash) % VEHICLE_COLORS.length];
};

function BatteryIcon({ level }) {
  if (level === undefined || level === null) return <Gauge size={13} strokeWidth={2} />;
  if (level < 15) return <BatteryWarning size={13} strokeWidth={2} />;
  if (level < 40) return <BatteryLow size={13} strokeWidth={2} />;
  if (level < 80) return <BatteryMedium size={13} strokeWidth={2} />;
  return <BatteryFull size={13} strokeWidth={2} />;
}

export default function ManageFleetPage() {
  const navigate = useNavigate();
  const { theme } = useTheme();
  const [vehicles, setVehicles] = useState([]);
  const [telemetryData, setTelemetryData] = useState({});
  const [command, setCommand] = useState("");
  const [selectedVehicle, setSelectedVehicle] = useState(null);
  const [activeTraces, setActiveTraces] = useState({});

  useEffect(() => {
    const socket = new SockJS('http://localhost:8080/ws-telemetry');
    const stompClient = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        fetch('http://localhost:8080/api/fleet/vehicles')
          .then(res => res.json())
          .then(data => {
            setVehicles(data);
            data.forEach(v => {
              stompClient.subscribe(`/topic/telemetry.${v.id}.position`, message => {
                const payload = JSON.parse(message.body);
                setTelemetryData(prev => ({ ...prev, [payload.vehicle_id]: payload }));
              });
            });
          })
          .catch(err => console.error("Error fetching vehicles:", err));
      },
    });

    stompClient.activate();
    return () => stompClient.deactivate();
  }, []);

  const handleCommandSubmit = (e) => {
    e.preventDefault();
    if (!command.trim()) return;
    console.log("Command submitted: ", command);
    setCommand("");
  };

  const vehicleById = useMemo(() => {
    const map = {};
    vehicles.forEach(v => { map[v.id] = v; });
    return map;
  }, [vehicles]);

  const activeCount = Object.keys(telemetryData).length;

  return (
    <div className="fleet-shell page-enter">
      <div className="sidebar">
        <button type="button" className="link-back" onClick={() => navigate('/')}>
          <ArrowLeft size={14} strokeWidth={2} />
          Back to Portal
        </button>

        <div className="sidebar-header">
          <div>
            <h2 className="sidebar-title">Fleet Orchestrator</h2>
            <p className="sidebar-subtitle">Live Telemetry &amp; Control</p>
          </div>
          <ThemeToggle />
        </div>

        {vehicles.length > 0 && (
          <div className="fleet-summary">
            <span><b>{vehicles.length}</b> registered</span>
            <span className="fleet-summary-dot">·</span>
            <span className="fleet-summary-active"><b>{activeCount}</b> active</span>
          </div>
        )}

        <div className="vehicle-list">
          {vehicles.length === 0 ? (
            <div className="empty-state">
              <SatelliteDish size={28} strokeWidth={1.5} />
              <p>Awaiting fleet registration...</p>
            </div>
          ) : (
            vehicles.map(v => {
              const live = telemetryData[v.id] || {};
              const isOnline = !!live.latitude;
              const isGround = v.category === 'GROUND';
              const isSelected = selectedVehicle === v.id;
              const vColor = getVehicleColor(v.id);

              return (
                <div key={v.id} className={`vehicle-card ${isSelected ? 'selected' : ''}`} onClick={() => setSelectedVehicle(v.id)}>
                  <div className="vehicle-card-top">
                    <div className="vehicle-card-name">
                      {/* NEW: Colored Icon Badge */}
                      <div className="vehicle-icon-badge" style={{ background: vColor, color: '#000', boxShadow: `0 0 10px ${vColor}40` }}>
                        {isGround ? <Truck size={15} strokeWidth={1.75} /> : <Plane size={15} strokeWidth={1.75} />}
                      </div>
                      <div>
                        <h4>{v.name}</h4>
                        <span className="vehicle-category">{v.category || 'UAV'}</span>
                      </div>
                    </div>
                    <div className={`status-pill ${isOnline ? 'is-active' : 'is-offline'}`}>
                      <span className="status-dot" />
                      {isOnline ? 'Active' : 'Offline'}
                    </div>
                  </div>

                  <div className="telemetry-grid">
                    <div>
                      <p className="telemetry-label">Latitude</p>
                      <p className="telemetry-value">{live.latitude ? live.latitude.toFixed(5) : '—'}</p>
                    </div>
                    <div>
                      <p className="telemetry-label">Longitude</p>
                      <p className="telemetry-value">{live.longitude ? live.longitude.toFixed(5) : '—'}</p>
                    </div>

                    {Object.keys(live)
                      .filter(key => !['vehicle_id', 'latitude', 'longitude', 'altitude', 'battery_level'].includes(key))
                      .map(customKey => (
                        <div key={customKey}>
                          <p className="telemetry-label">{customKey.replace(/_/g, ' ')}</p>
                          <p className="telemetry-value">{live[customKey]}</p>
                        </div>
                      ))
                    }
                  </div>

                  {live.altitude !== undefined && (
                    <div className="vehicle-card-footer">
                      <span><Gauge size={12} strokeWidth={2} /> {live.altitude.toFixed(1)}m</span>
                      {live.battery_level !== undefined && (
                        <span className={live.battery_level < 20 ? 'is-critical' : ''}>
                          <BatteryIcon level={live.battery_level} /> {live.battery_level}%
                        </span>
                      )}
                    </div>
                  )}

                  <div
                    style={{
                      marginTop: '12px', paddingTop: '12px', borderTop: '1px solid var(--border-light, rgba(128,128,128,0.15))',
                      display: 'flex', alignItems: 'center'
                    }}
                    onClick={(e) => e.stopPropagation()}
                  >
                    <div style={{
                                          marginTop: '12px', paddingTop: '12px', borderTop: '1px solid var(--border-light, rgba(128,128,128,0.15))',
                                          display: 'flex', alignItems: 'center', justifyContent: 'space-between'
                                        }}
                                        onClick={(e) => e.stopPropagation()}
                                      >
                                        <label style={{ fontSize: '12px', display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', color: 'var(--text-primary)', fontWeight: '500' }}>
                                          <input
                                            type="checkbox"
                                            checked={!!activeTraces[v.id]}
                                            onChange={() => setActiveTraces(prev => ({ ...prev, [v.id]: !prev[v.id] }))}
                                            style={{ accentColor: vColor, cursor: 'pointer' }}
                                          />
                                          <Route size={14} color={vColor} />
                                          Show 3D Trace
                                        </label>

                                        {/* NEW: Button to open full history DVR */}
                                        <button
                                          onClick={() => navigate(`/vehicle/${v.id}`)}
                                          style={{
                                            background: 'transparent', border: `1px solid ${vColor}50`, color: vColor,
                                            padding: '4px 10px', borderRadius: '6px', fontSize: '11px', fontWeight: '600',
                                            cursor: 'pointer', textTransform: 'uppercase'
                                          }}
                                        >
                                          Full History
                                        </button>
                                      </div>
                  </div>

                </div>
              );
            })
          )}
        </div>
      </div>

      <div className="map-panel">
        <FleetMap
          telemetryData={telemetryData}
          vehicleById={vehicleById}
          theme={theme}
          selectedVehicle={selectedVehicle}
          setSelectedVehicle={setSelectedVehicle}
          activeTraces={activeTraces}
        />

        <div className="command-bar-wrap">
          <form onSubmit={handleCommandSubmit} className="command-bar">
            <Sparkles size={16} strokeWidth={2} className="command-bar-icon" />
            <input
              type="text"
              value={command}
              onChange={(e) => setCommand(e.target.value)}
              placeholder="Ask the AI to orchestrate the fleet (e.g., 'Deploy Alpha to grid sector 4')"
            />
            <button type="submit" className="btn btn-primary btn-compact">
              Dispatch
              <Send size={14} strokeWidth={2} />
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
